                l2Sender == L2_BASE_TOKEN_SYSTEM_CONTRACT_ADDR ||
                l2Sender == __DEPRECATED_l2BridgeAddress[_finalizeWithdrawalParams.chainId];
            if (!isL2SenderCorrect) {
                revert WrongL2Sender(l2Sender);
